/**
 * Generates the two files the official registry expects, straight from the
 * build output, so a submission never drifts from what was actually built.
 *
 * The registry (github.com/Sharkord/plugins) stores metadata only:
 *
 *   plugins/<id>/plugin.json
 *   plugins/<id>/versions/<version>.json
 *
 * Output lands in `registry/plugins/<id>/`, mirroring that tree, so it can be
 * copied into a fork of the registry as-is. `plugins.json` is regenerated by
 * the maintainers' `build-index.ts` — never edit it by hand.
 *
 * Run with `bun run registry` after `bun run build`.
 */
import fs from "fs/promises";
import path from "path";

const root = process.cwd();
const manifestPath = path.join(root, "manifest.json");
const packagePath = path.join(root, "package.json");

const manifest = (await Bun.file(manifestPath).json()) as {
  id: string;
  name: string;
  author: string;
  description: string;
  homepage?: string;
  logo?: string;
  version: string;
};

const pkg = (await Bun.file(packagePath).json()) as {
  repository?: string | { url?: string };
};

const repo = (
  typeof pkg.repository === "string" ? pkg.repository : (pkg.repository?.url ?? "")
)
  .replace(/^https?:\/\/github\.com\//, "")
  .replace(/\.git$/, "")
  .trim();

const fail = (message: string): never => {
  console.error(`registry: ${message}`);
  process.exit(1);
  throw new Error(message);
};

// Mirrors the registry's zod schema: id is lowercase/digits/dashes, logo is
// mandatory there even though the host treats it as optional.
if (!/^[a-z0-9-]+$/.test(manifest.id)) fail(`invalid plugin id "${manifest.id}"`);
if (!manifest.logo) fail("manifest.json needs a logo URL before submitting");
if (!repo) fail("package.json needs a repository URL before submitting");

const buildVersionPath = path.join(root, "dist", `${manifest.version}.json`);
const built = (await Bun.file(buildVersionPath)
  .json()
  .catch(() => fail(`missing ${buildVersionPath} — run bun run build first`))) as {
  version: string;
  checksum: string;
  size: number;
  sdkVersion: number;
  timestamp: number;
};

const downloadUrl = `https://github.com/${repo}/releases/download/v${manifest.version}/${manifest.id}-${manifest.version}.tar.gz`;

const pluginJson = {
  id: manifest.id,
  name: manifest.name,
  description: manifest.description,
  author: manifest.author,
  logo: manifest.logo,
  homepage: manifest.homepage,
  screenshots: [] as string[],
  verified: false,
  // The registry's TAGS / CATEGORIES allow-lists are currently empty, so
  // anything else is rejected by `bun run validate` on the PR.
  tags: [] as string[],
  categories: [] as string[],
};

const versionJson = {
  version: manifest.version,
  downloadUrl,
  checksum: built.checksum,
  sdkVersion: built.sdkVersion,
  size: built.size,
  timestamp: built.timestamp,
};

const outDir = path.join(root, "registry", "plugins", manifest.id);
await fs.mkdir(path.join(outDir, "versions"), { recursive: true });
await fs.writeFile(
  path.join(outDir, "plugin.json"),
  `${JSON.stringify(pluginJson, null, 2)}\n`,
  "utf-8",
);
await fs.writeFile(
  path.join(outDir, "versions", `${manifest.version}.json`),
  `${JSON.stringify(versionJson, null, 2)}\n`,
  "utf-8",
);

console.log(`Wrote ${path.relative(root, outDir)}`);
console.log(`  plugin.json`);
console.log(`  versions/${manifest.version}.json  (${built.size} B, sha256 ${built.checksum.slice(0, 12)}…)`);
console.log(`Release asset expected at ${downloadUrl}`);
